diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..91c9c63 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -170,6 +170,30 @@ assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: t
 assert.equal(profiles.evaluateModelProof(local, { model: 'other-model', trusted: true }).status, 'failed');
 assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: false }).status, 'unknown');

+// Adversarial: a signed, trusted observation naming a different model must
+// still fail the requested executor -- trust in the source cannot launder a
+// model substitution. Telemetry the substituted observation never reported
+// must stay honestly unknown, not be promoted to zero/known.
+const substituted = { model: 'other-model', trusted: true };
+assert.equal(profiles.evaluateModelProof(local, substituted).status, 'failed');
+const substitutionState = profiles.missionControlExecutorState({ profile: local, observation: substituted, wrapper: null });
+assert.equal(substitutionState.requested_model, local.model);
+assert.equal(substitutionState.observed_model, 'other-model');
+assert.equal(substitutionState.model_status, 'failed');
+assert.notEqual(substitutionState.model_status, 'passed');
+assert.equal(substitutionState.cost, null);
+assert.equal(substitutionState.cost_status, 'unknown');
+assert.equal(substitutionState.duration_ms, null);
+assert.equal(substitutionState.duration_status, 'unknown');
+assert.equal(substitutionState.tokens, null);
+assert.equal(substitutionState.tokens_status, 'unknown');
+const substitutionReplay = profiles.publicExecutorReplay({ profile: local, observation: substituted, wrapper: null });
+assert.equal(substitutionReplay.observed_model, 'other-model');
+assert.equal(substitutionReplay.model_status, 'failed');
+assert.equal(substitutionReplay.cost_status, 'unknown');
+assert.equal(substitutionReplay.duration_status, 'unknown');
+assert.equal(substitutionReplay.tokens_status, 'unknown');
+
 const missionUnknown = profiles.missionControlExecutorState({ profile: local, observation: null, wrapper: null });
 assert.equal(missionUnknown.requested_model, local.model);
 assert.equal(missionUnknown.observed_model, null);
